const nl_rpc_contract *nl_rpc_contract_lookup(nl_daemon_id service,
                                              nl_rpc_method method) {
    for (size_t i = 0; i < nl_rpc_contract_count(); i++) {
        if (g_contracts[i].service == service &&
            g_contracts[i].method == method)
            return &g_contracts[i];
    }
    return NULL;
}

size_t nl_rpc_contract_count(void) {
    return sizeof(g_contracts) / sizeof(g_contracts[0]);
}

const nl_rpc_contract *nl_rpc_contract_at(size_t index) {
    return index < nl_rpc_contract_count() ? &g_contracts[index] : NULL;
}

bool nl_rpc_contract_caller_allowed(const nl_rpc_contract *contract,
                                    nl_daemon_id caller) {
    if (!contract)
        return false;
    if (caller == NL_DAEMON_INTERNAL)
        return contract->internal_authority_allowed;
    if (caller < NL_DAEMON_MGMTD || caller > NL_DAEMON_IDENTITYD)
        return false;
    return (contract->caller_mask & D(caller)) != 0;
}

bool nl_rpc_contract_payload_valid(nl_rpc_payload_format format,
                                   const u8 *payload, u32 payload_len,
                                   u32 max_payload_len) {
    const u8 *separator;

    if (payload_len > max_payload_len || (payload_len > 0 && !payload))
        return false;
    if (format == NL_RPC_PAYLOAD_NONE)
        return payload_len == 0;
    if (format == NL_RPC_PAYLOAD_BINARY)
        return true;
    if (format == NL_RPC_PAYLOAD_PATH_VALUE) {
        if (payload_len == 0 || payload[0] == '\0')
            return false;
        separator = memchr(payload, '\0', payload_len);
        if (!separator || separator + 1 == payload + payload_len)
            return true;
        return memchr(separator + 1, '\0',
                      (size_t)((payload + payload_len) - separator - 1)) == NULL;
    }
    if (format != NL_RPC_PAYLOAD_TEXT)
        return false;
    return payload_len == 0 || memchr(payload, '\0', payload_len) == NULL;
}

const char *nl_rpc_access_name(nl_rpc_access access) {
    switch (access) {
    case NL_RPC_ACCESS_INTERNAL: return "internal";
    case NL_RPC_ACCESS_VIEW: return "view";
    case NL_RPC_ACCESS_CONFIG: return "config";
    case NL_RPC_ACCESS_COMMIT: return "commit";
    case NL_RPC_ACCESS_CLEAR: return "clear";
    case NL_RPC_ACCESS_ADMIN: return "admin";
    }
    return "unknown";
}
